CREATE SCHEMA IF NOT EXISTS "public";
CREATE TABLE "user" ("id" TEXT NOT NULL,"name" TEXT NOT NULL,"email" TEXT NOT NULL,"emailVerified" BOOLEAN NOT NULL DEFAULT false,"image" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,"masterPasswordHash" TEXT,"keySalt" TEXT,"masterSetupAt" TIMESTAMP(3),CONSTRAINT "user_pkey" PRIMARY KEY ("id"));
CREATE TABLE "session" ("id" TEXT NOT NULL,"expiresAt" TIMESTAMP(3) NOT NULL,"token" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,"ipAddress" TEXT,"userAgent" TEXT,"userId" TEXT NOT NULL,CONSTRAINT "session_pkey" PRIMARY KEY ("id"));
CREATE TABLE "account" ("id" TEXT NOT NULL,"accountId" TEXT NOT NULL,"providerId" TEXT NOT NULL,"userId" TEXT NOT NULL,"accessToken" TEXT,"refreshToken" TEXT,"idToken" TEXT,"accessTokenExpiresAt" TIMESTAMP(3),"refreshTokenExpiresAt" TIMESTAMP(3),"scope" TEXT,"password" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "account_pkey" PRIMARY KEY ("id"));
CREATE TABLE "verification" ("id" TEXT NOT NULL,"identifier" TEXT NOT NULL,"value" TEXT NOT NULL,"expiresAt" TIMESTAMP(3) NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "verification_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Category" ("id" TEXT NOT NULL,"name" TEXT NOT NULL,"color" TEXT NOT NULL DEFAULT '#3B82F6',"icon" TEXT NOT NULL DEFAULT 'folder',"userId" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "Category_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Credential" ("id" TEXT NOT NULL,"name" TEXT NOT NULL,"username" TEXT NOT NULL,"website" TEXT,"email" TEXT,"encryptedPassword" TEXT NOT NULL,"iv" TEXT NOT NULL,"authTag" TEXT NOT NULL,"algorithmVersion" INTEGER NOT NULL DEFAULT 1,"notes" TEXT,"categoryId" TEXT,"favorite" BOOLEAN NOT NULL DEFAULT false,"userId" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,"lastViewed" TIMESTAMP(3),CONSTRAINT "Credential_pkey" PRIMARY KEY ("id"));
CREATE TABLE "ActivityLog" ("id" TEXT NOT NULL,"userId" TEXT NOT NULL,"timestamp" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"device" TEXT NOT NULL,"browser" TEXT NOT NULL,"os" TEXT NOT NULL,"ip" TEXT NOT NULL,"action" TEXT NOT NULL,"description" TEXT NOT NULL,"metadata" JSONB,CONSTRAINT "ActivityLog_pkey" PRIMARY KEY ("id"));
CREATE TABLE "AccountSettings" ("id" TEXT NOT NULL,"userId" TEXT NOT NULL,"theme" TEXT NOT NULL DEFAULT 'system',"autoLockMinutes" INTEGER NOT NULL DEFAULT 15,"clipboardClearSeconds" INTEGER NOT NULL DEFAULT 30,"twoFactorEnabled" BOOLEAN NOT NULL DEFAULT false,"biometricUnlockEnabled" BOOLEAN NOT NULL DEFAULT false,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "AccountSettings_pkey" PRIMARY KEY ("id"));
CREATE TABLE "RateLimitBucket" ("id" TEXT NOT NULL,"key" TEXT NOT NULL,"userId" TEXT,"count" INTEGER NOT NULL DEFAULT 1,"windowStart" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "RateLimitBucket_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "user_email_key" ON "user"("email");
CREATE UNIQUE INDEX "session_token_key" ON "session"("token");
CREATE INDEX "session_userId_idx" ON "session"("userId");
CREATE INDEX "account_userId_idx" ON "account"("userId");
CREATE UNIQUE INDEX "account_providerId_accountId_key" ON "account"("providerId", "accountId");
CREATE INDEX "verification_identifier_idx" ON "verification"("identifier");
CREATE INDEX "Category_userId_updatedAt_idx" ON "Category"("userId", "updatedAt");
CREATE UNIQUE INDEX "Category_userId_name_key" ON "Category"("userId", "name");
CREATE INDEX "Credential_userId_updatedAt_idx" ON "Credential"("userId", "updatedAt");
CREATE INDEX "Credential_userId_lastViewed_idx" ON "Credential"("userId", "lastViewed");
CREATE INDEX "Credential_userId_favorite_idx" ON "Credential"("userId", "favorite");
CREATE INDEX "Credential_categoryId_idx" ON "Credential"("categoryId");
CREATE INDEX "ActivityLog_userId_timestamp_idx" ON "ActivityLog"("userId", "timestamp");
CREATE INDEX "ActivityLog_userId_action_idx" ON "ActivityLog"("userId", "action");
CREATE UNIQUE INDEX "AccountSettings_userId_key" ON "AccountSettings"("userId");
CREATE INDEX "RateLimitBucket_userId_idx" ON "RateLimitBucket"("userId");
CREATE INDEX "RateLimitBucket_windowStart_idx" ON "RateLimitBucket"("windowStart");
CREATE UNIQUE INDEX "RateLimitBucket_key_windowStart_key" ON "RateLimitBucket"("key", "windowStart");
ALTER TABLE "session" ADD CONSTRAINT "session_userId_fkey" FOREIGN KEY ("userId") REFERENCES "user"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "account" ADD CONSTRAINT "account_userId_fkey" FOREIGN KEY ("userId") REFERENCES "user"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "Category" ADD CONSTRAINT "Category_userId_fkey" FOREIGN KEY ("userId") REFERENCES "user"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "Credential" ADD CONSTRAINT "Credential_userId_fkey" FOREIGN KEY ("userId") REFERENCES "user"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "Credential" ADD CONSTRAINT "Credential_categoryId_fkey" FOREIGN KEY ("categoryId") REFERENCES "Category"("id") ON DELETE SET NULL ON UPDATE CASCADE;
ALTER TABLE "ActivityLog" ADD CONSTRAINT "ActivityLog_userId_fkey" FOREIGN KEY ("userId") REFERENCES "user"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "AccountSettings" ADD CONSTRAINT "AccountSettings_userId_fkey" FOREIGN KEY ("userId") REFERENCES "user"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "RateLimitBucket" ADD CONSTRAINT "RateLimitBucket_userId_fkey" FOREIGN KEY ("userId") REFERENCES "user"("id") ON DELETE CASCADE ON UPDATE CASCADE;
